export function createOptimisticStore(initialState) {
  let base = initialState;
  let visibleState = initialState;
  let pending = [];
  const listeners = [];

  function idsEqual(a, b) {
    return a === b || (a !== a && b !== b);
  }

  function findPendingIndex(id) {
    for (let index = 0; index < pending.length; index += 1) {
      if (idsEqual(pending[index].id, id)) {
        return index;
      }
    }
    return -1;
  }

  function replay(startState, changes) {
    let state = startState;

    for (let index = 0; index < changes.length; index += 1) {
      state = changes[index].update(state);
    }

    return state;
  }

  function notify() {
    const snapshot = listeners.slice();

    for (let index = 0; index < snapshot.length; index += 1) {
      const listener = snapshot[index].listener;

      try {
        listener();
      } catch {
        // Listener errors must not interrupt notification.
      }
    }
  }

  function getState() {
    return visibleState;
  }

  function apply(id, update) {
    if (findPendingIndex(id) !== -1) {
      throw new Error("A pending change with this id already exists");
    }

    const nextVisibleState = update(visibleState);

    pending = pending.concat({ id, update });
    visibleState = nextVisibleState;
    notify();
  }

  function confirm(id) {
    const index = findPendingIndex(id);

    if (index === -1) {
      return false;
    }

    const change = pending[index];
    const remaining = pending
      .slice(0, index)
      .concat(pending.slice(index + 1));

    const nextBase = change.update(base);
    const nextVisibleState = replay(nextBase, remaining);

    base = nextBase;
    pending = remaining;
    visibleState = nextVisibleState;
    notify();

    return true;
  }

  function rollback(id) {
    const index = findPendingIndex(id);

    if (index === -1) {
      return false;
    }

    const remaining = pending
      .slice(0, index)
      .concat(pending.slice(index + 1));

    const nextVisibleState = replay(base, remaining);

    pending = remaining;
    visibleState = nextVisibleState;
    notify();

    return true;
  }

  function subscribe(listener) {
    const subscription = { listener };
    let subscribed = true;

    listeners.push(subscription);

    return function unsubscribe() {
      if (!subscribed) {
        return;
      }

      subscribed = false;
      const index = listeners.indexOf(subscription);

      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  return {
    getState,
    apply,
    confirm,
    rollback,
    subscribe,
  };
}
